import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

@Controller('api/v1')
export class FnSfr03212Controller {
  @Post('/expense-resolutions/:expenseResolutionId/submit')
  @HttpCode(200)
  async submitExpenseResolution(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const id = req.params['expenseResolutionId'];
    if (!/^\d+$/.test(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결의서 ID 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT expense_resolution_id AS "expenseResolutionId", status, partner_id AS "partnerId", requisition_id AS "requisitionId", resolution_amount AS "resolutionAmount" FROM expense_resolution WHERE expense_resolution_id = CAST(:id AS bigint) FOR UPDATE',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'EXPENSE_RESOLUTION_NOT_FOUND', '결의서를 찾을 수 없습니다.');
      }
      const row = rows[0];
      // 전환표: 기안 상태에서만 상신할 수 있다.
      if (row.status !== '기안') {
        throw new ApiError(409, 'EXPENSE_RESOLUTION_INVALID_STATUS', '기안 상태의 결의서만 상신할 수 있습니다.');
      }
      // 필수값 누락은 상신 차단 (API 표: 422 BUDGET_LIMIT_EXCEEDED)
      if (row.partnerId === null || row.partnerId === undefined) {
        throw new ApiError(422, 'BUDGET_LIMIT_EXCEEDED', '거래처가 없어 상신할 수 없습니다. 거래처를 입력해 주세요.');
      }
      // 연계 품의서가 있으면 품의 범위 내에서 결의한다.
      if (row.requisitionId !== null && row.requisitionId !== undefined) {
        const reqs = await db.query(
          'SELECT requisition_amount AS "requisitionAmount" FROM requisition WHERE requisition_id = CAST(:requisitionId AS bigint)',
          { requisitionId: String(row.requisitionId) },
        );
        if (reqs.length > 0 && Number(row.resolutionAmount) > Number(reqs[0].requisitionAmount)) {
          throw new ApiError(422, 'BUDGET_LIMIT_EXCEEDED', '결의 금액이 연계 품의서의 품의 금액을 초과하여 상신할 수 없습니다.');
        }
      }
      // 가정: 결재양식은 사용 중인 양식 중 가장 먼저 등록된 것을 쓴다 (출처가 스펙에 없음).
      const forms = await db.query(
        "SELECT approval_form_id AS \"approvalFormId\" FROM approval_form WHERE use_status = '사용' ORDER BY approval_form_id LIMIT 1",
        {},
      );
      if (forms.length === 0) {
        throw new ApiError(422, 'BUDGET_LIMIT_EXCEEDED', '사용 중인 결재양식이 없어 상신할 수 없습니다.');
      }
      // S3 결재 연계: 전자결재 문서를 상신 상태로 만든다.
      const docs = await db.query(
        "INSERT INTO approval_document (document_no, approval_form_id, drafter_id, title, approval_status, submitted_at, created_at, updated_at) VALUES ('ER-' || :id || '-' || to_char(now(), 'YYYYMMDDHH24MISSMS'), CAST(:formId AS bigint), CAST(:userId AS bigint), '지출결의서 ' || :id, '결재대기', now(), now(), now()) RETURNING approval_document_id AS \"approvalDocumentId\"",
        { id, formId: String(forms[0].approvalFormId), userId: user.id },
      );
      const approvalDocumentId = docs[0].approvalDocumentId;
      const updated = await db.query(
        "UPDATE expense_resolution SET status = '결재대기', approval_document_id = CAST(:docId AS bigint), updated_at = now() WHERE expense_resolution_id = CAST(:id AS bigint) AND status = '기안' RETURNING expense_resolution_id AS \"expenseResolutionId\", approval_document_id AS \"approvalDocumentId\", status",
        { id, docId: String(approvalDocumentId) },
      );
      return updated[0];
    });
  }
}

