import { useState } from 'react';
import { Band, Badge, DataTable, DateText, Drawer, Field, Form, LookupSelect, Pairs, RefName, call } from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr03212Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [resolutionId, setResolutionId] = useState<number | string>('');
  const [results, setResults] = useState<Row[]>([]);
  const [detail, setDetail] = useState<Row | null>(null);

  async function submit() {
    if (resolutionId === '') {
      throw new Error('상신할 지출결의서를 선택해 주세요.');
    }
    const res = await call('POST', '/expense-resolutions/' + resolutionId + '/submit', role, {});
    const done: Row = { ...res, submittedAt: new Date().toISOString() };
    setResults([done, ...results.filter((r) => r.expenseResolutionId !== res.expenseResolutionId)]);
    setOpen(false);
    setResolutionId('');
    notify('지출결의서를 상신했습니다.');
  }

  if (detail) {
    return (
      <div className="doc">
        <button className="ghost" onClick={() => setDetail(null)}>목록으로</button>
        <section className="box">
          <h2>상신 결과</h2>
          <Pairs
            items={[
              ['결의서', <RefName table="expense_resolution" role={role} value={detail.expenseResolutionId} />],
              ['전자결재 문서', <RefName table="approval_document" role={role} value={detail.approvalDocumentId} />],
              ['진행 상태', <Badge value={detail.status} />],
              ['상신 일시', <DateText value={detail.submittedAt} time />],
            ]}
          />
        </section>
      </div>
    );
  }

  return (
    <div className="doc">
      <h1>지출결의서 상신</h1>
      <Band total={results.length}>
        <button onClick={() => setOpen(true)}>지출결의서 상신</button>
      </Band>
      <DataTable
        columns={[
          { key: 'expenseResolutionId', label: '결의서 ID', render: (r) => <RefName table="expense_resolution" role={role} value={r.expenseResolutionId} /> },
          { key: 'approvalDocumentId', label: '전자결재 문서', render: (r) => <RefName table="approval_document" role={role} value={r.approvalDocumentId} /> },
          { key: 'status', label: '진행 상태', render: (r) => <Badge value={r.status} /> },
          { key: 'submittedAt', label: '상신 일시', render: (r) => <DateText value={r.submittedAt} time /> },
        ]}
        rows={results}
        onRowClick={(r) => setDetail(r)}
        empty="아직 상신한 결의서가 없습니다. 지출결의서 상신 버튼을 눌러 시작하세요."
      />
      {open && (
        <Drawer title="지출결의서 상신" onClose={() => setOpen(false)}>
          <Form
            onSubmit={submit}
            submit="상신"
            note="상신하면 전자결재가 연계되어 결재대기 상태가 되며, 기안 상태로 되돌릴 수 없습니다."
          >
            <Field label="결의서 ID" required wide>
              <LookupSelect table="expense_resolution" role={role} value={resolutionId} onChange={setResolutionId} placeholder="결의서 선택" />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
